import{z as n,x as B,o as t,c as d,q as l,j as A,D as E,d as r,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"机台软件与配方","description":"","frontmatter":{"title":"机台软件与配方","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-recipe-software.md","filePath":"litho/tool-recipe-software.md","lastUpdated":1791413859000}'),p={name:"litho/tool-recipe-software.md"};function D(h,a,f,m,C,u){const o=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="机台软件与配方" tabindex="-1">机台软件与配方 <a class="header-anchor" href="#机台软件与配方" aria-label="Permalink to &quot;机台软件与配方&quot;">​</a></h1><div class="epigraph"><p>曝光机是一台会跑状态机的精密仪器。配方把照明、剂量、对准、扫描编成可重复的剧本；软件缺陷会表现为「随机套刻」。</p><footer>—— 机台与主机联机见 SEMI E30（GEM）；作业与载具模型见 E40 / E87 / E94 作业族标准</footer></div><p><a href="/litho/tool-uptime-mtbf">上一课</a>把停机算进稼动。缺口是：很多停机和偏移来自配方与联机软件，不是轴承。本课钉配方软件，校准周期收束本单元。同一台机，两套配方就是两台机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一硬件，配方选错照明、选错对准标记、扫描向反了，CD 和套刻会整批废。版本：胶换了剂量表没升版。联机：轨道送来的片 ID 对不上 job。把所有偏移写成光学，会漏软件配置。</p><p>展开：配方是一叠参数——照明设置、NA 与 σ、剂量表、对准策略（标记组、捕获窗）、扫描方向、场图边场处理。选错一项就成批显形：照明错是整批 CD 偏移，标记错是对准报错或盲曝，扫描向反是套刻按场翻转。版本更隐蔽：胶批换了、剂量表没升版，漂移被误判成工艺或硬件过期。联机问题则表现成「随机」：片 ID 与 job 对不上、状态机卡半途，日志没留好就查无实据。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方版本进变更控制，与胶批、掩模 ID 绑定。仿真/干跑检查标记是否在窗、场图是否越界。日志：哪条校正表、哪次校准被用。与 APC 课分工：APC 改剂量套刻偏置，本课管机台是否执行了那张配方。</p><p>工程流程：生命周期分生成、下发、执行三段。生成端由层定义加机台能力文件出配方，干跑校验标记在窗、场图不越界、剂量在表内；下发经 SEMI E30 GEM 一类的主机联机界面（E40/E87/E94 管作业与载具），配方版本与掩模 ID、胶批绑定；执行端日志必须能答出「用的哪版配方、哪张校正表、哪次校准快照」。</p>',9)),(t(),A(s,null,{default:E(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E9%85%8D%E6%96%B9%E7%89%88%E6%9C%AC%22%5D%20--%3E%20JOB%5B%22%E6%9C%AC%E6%89%B9%20job%22%5D%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%20ID%22%5D%20--%3E%20JOB%0A%20%20RES%5B%22%E8%83%B6%20%2F%20%E8%BD%A8%E9%81%93%22%5D%20--%3E%20JOB%0A%20%20JOB%20--%3E%20EXE%5B%22%E6%89%AB%E6%8F%8F%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"把配方文件做摘要（hash）写进批历史，复盘才有「当时执行了什么」的第一手证据；没有它，事故调查会在「确定改过剂量表吗」这层空转。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"状态机翻译成大白话：机台内部有一张「现在在哪一站、下一步允许去哪」的地图，装载、预对准、对准、曝光各是一站。软件的一切行为就是按这张地图走；「卡住」多半是走到了地图上没铺路的一步。")],-1)),a[6]||(a[6]=e("p",null,"状态机：装载 → 预对准 → 对准 → 曝光 → 卸载。中断恢复若丢校正表，会留下一场「幽灵指纹」。时间同步：机台钟与计量钟差，APC 会喂错批。",-1)),(t(),A(s,null,{default:E(()=>[i(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22%E8%A3%85%E8%BD%BD%22%5D%20--%3E%20PA%5B%22%E9%A2%84%E5%AF%B9%E5%87%86%22%5D%0A%20%20PA%20--%3E%20AL%5B%22%E5%AF%B9%E5%87%86%22%5D%0A%20%20AL%20--%3E%20EX%5B%22%E6%9B%9D%E5%85%89%22%5D%0A%20%20EX%20--%3E%20UL%5B%22%E5%8D%B8%E8%BD%BD%22%5D%0A%20%20AL%20--%3E%20INT%5B%22%E6%80%A5%E5%81%9C%E6%88%96%E6%8E%89%E7%94%B5%22%5D%0A%20%20EX%20--%3E%20INT%0A%20%20INT%20--%3E%20REC%7B%22%E6%81%A2%E5%A4%8D%E7%82%B9%E5%AE%8C%E6%95%B4%3F%22%7D%0A%20%20REC%20--%3E%7C%E6%A0%A1%E6%AD%A3%E8%A1%A8%E4%B8%8E%E5%BF%AB%E7%85%A7%E5%9C%A8%7C%20OK%5B%22%E5%8E%9F%E5%AD%90%E6%81%A2%E5%A4%8D%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20REC%20--%3E%7C%E6%A0%A1%E6%AD%A3%E8%A1%A8%E4%B8%A2%E5%A4%B1%7C%20GH%5B%22%E5%B9%BD%E7%81%B5%E6%8C%87%E7%BA%B9%3A%20%E9%9A%8F%E6%9C%BA%E5%A5%97%E5%88%BB%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>写透一点：状态机里最容易出鬼的是中断恢复：急停、掉电后，恢复点必须连校正表与对准快照原子地回来——丢了校正表的后半批留下一场「幽灵指纹」，现场是随机套刻，日志是状态机停在半句。MES 与设备端的差分排查有固定次序：先对配方摘要，再对校正表版本与校准日期，最后才轮到硬件；多数「随机套刻」走到第二层就现形。时间同步是暗坑：机台钟与计量钟差会让 APC 把偏置喂错批，钟差对齐前调工艺没用。</p><p><span class="marginnote">常见误区：把所有漂移都往光学或机械上猜。实际排查次序是软件配置优先——配方摘要对得上，校正表版本与校准日期对不上，问题就已经定位了一半，动硬件反而是最后一步。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 APC 怎么算偏置（<a href="/litho/apc">APC</a>、<a href="/litho/feedforward-feedback-r2r">前馈反馈</a>课域），也不写配方引用的版图从哪来（<a href="/litho/mask-data-prep">掩模数据准备</a>课）；状态机只覆盖单机，track 与 scanner 的交接时序归<a href="/litho/track-scanner-link">联机</a>课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配方是可版本化的光学与运动剧本。</li><li>联机状态与日志是「随机」失效的第一现场。</li><li>下一课校准周期：配方再对，零点漂了仍偏。</li><li>出处：对准与 APC 课；SEMI 作业管理通识。</li></ul>',6))])}const P=n(p,[["render",D]]);export{_ as __pageData,P as default};
